from __future__ import absolute_import

from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3.pages import v22r2
from taf.selenium.sbts_fsm3.pages.modals import BlockOrUnBlockRatModal


class BtsStatus(v22r2.BtsStatus):
    """
    The class corresponding to BTS status page on selenium_sbts web, all operations under BTS status
    page will be implemented or added in its corresponding classes.
    """

    def __init__(self, driver):
        super(BtsStatus, self).__init__(driver)
        self._site_view = SiteViewPage(driver)


class SiteViewPage(v22r2.bts_status.SiteViewPage):
    """
    As a class will be called by BtsStatus, all operations on Site View will be implemented under this class.
    """
    _MENU_ROUTE_LIST = ['BTS Status', 'Site Runtime View', 'Site View']

    def __init__(self, driver):
        super(SiteViewPage, self).__init__(driver)
        self._view_panel = SiteViewPageViewPanel(driver)

    def block_rat(self, rat, timeout=60):
        self._view_panel.block_rat(rat, timeout)

    def unblock_rat(self, rat, timeout=60):
        self._view_panel.unblock_rat(rat, timeout)


class SiteViewPageViewPanel(v22r2.bts_status.SiteViewPageViewPanel):
    RAT_BLOCK_UNBLOCK_BUTTON = '//*[@title="RAT Block/Unblock"]'
    OPERATE_RAT_SELECTION = RAT_BLOCK_UNBLOCK_BUTTON + '/ancestor::button/following-sibling::ul//span[text()="{}"]'

    def __init__(self, driver):
        super(SiteViewPageViewPanel, self).__init__(driver)

    def block_rat(self, rat, timeout=60):
        selection = 'Block {}'.format(rat.upper())
        self.select_element_from_dropdown_list_by_text_and_click(
            selection,
            (By.XPATH, self.RAT_BLOCK_UNBLOCK_BUTTON),
            (By.XPATH, self.OPERATE_RAT_SELECTION.format(selection)),
            timeout
        )
        self.block_or_unblock_rat('block', timeout)

    def unblock_rat(self, rat, timeout=60):
        selection = 'Unblock {}'.format(rat.upper())
        self.select_element_from_dropdown_list_by_text_and_click(
            selection,
            (By.XPATH, self.RAT_BLOCK_UNBLOCK_BUTTON),
            (By.XPATH, self.OPERATE_RAT_SELECTION.format(selection)),
            timeout
        )
        self.block_or_unblock_rat('unblock', timeout)

    def block_or_unblock_rat(self, operation, timeout=60):
        modal = BlockOrUnBlockRatModal(self.driver)
        modal.wait_until_block_or_unblock_rat_modal_appear(timeout)
        if operation == 'block':
            modal.block(timeout)
        if operation == 'unblock':
            modal.unblock(timeout)
